package ec.edu.unl.sec.selfassessment.application;
import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import ec.edu.unl.sec.evaluationmodel.application.*;import ec.edu.unl.sec.identityaccess.application.*;import ec.edu.unl.sec.selfassessment.support.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
class SelfAssessmentServiceTest{@Test void createsAndActivatesUsingPublishedModel(){var repo=new InMemorySelfAssessmentRepository();UUID actor=UUID.randomUUID(),career=UUID.randomUUID(),model=UUID.randomUUID(),version=UUID.randomUUID(),indicator=UUID.randomUUID();ModelCatalogPort models=mock(ModelCatalogPort.class);when(models.publishedVersion(version)).thenReturn(Optional.of(new ModelCatalogPort.PublishedModel(model,version,1,List.of(new ModelCatalogPort.Indicator(indicator,"I","Indicador")),null,null)));AuthorizationPort auth=mock(AuthorizationPort.class);when(auth.isAllowed(any(),any(),any())).thenReturn(true);var service=new SelfAssessmentService(repo,models,()->Optional.of(new CurrentActorPort.Actor(actor,false)),auth,mock(SelfAssessmentAuditService.class));var draft=service.create(career,"P-1","Proceso",LocalDate.now(),LocalDate.now().plusDays(10),version,UUID.randomUUID());var active=service.activate(draft.id(),0,UUID.randomUUID());assertThat(active.modelVersionId()).isEqualTo(version);assertThat(active.indicators()).hasSize(1);}}
